if (value == null)
				return "null";


			var valueAsType = value as Type;

			if (valueAsType != null)
				return string.Format(CultureInfo.CurrentCulture, "typeof({0})", FormatTypeName(valueAsType, fullTypeName: true));


			try
			{
				if (value.GetType().GetTypeInfo().IsEnum)
					return FormatEnumValue(value);

				if (value is char)
					return FormatCharValue((char)value);

				if (value is float)
					return FormatFloatValue(value);

				if (value is double)
					return FormatDoubleValue(value);

				if (value is DateTime || value is DateTimeOffset)
					return FormatDateTimeValue(value);

				var stringParameter = value as string;
				if (stringParameter != null)
					return FormatStringValue(stringParameter);

#if !XUNIT_ARGUMENTFORMATTER_PRIVATE
				var tracker = value as CollectionTracker;
				if (tracker != null)
					return tracker.FormatStart(depth);
#endif

				var enumerable = value as IEnumerable;
				if (enumerable != null)
					return FormatEnumerableValue(enumerable, depth);

				var type = value.GetType();
				var typeInfo = type.GetTypeInfo();

				if (tupleInterfaceType != null && type.GetTypeInfo().ImplementedInterfaces.Contains(tupleInterfaceType))
					return FormatTupleValue(value, depth);

				if (typeInfo.IsValueType)
					return FormatValueTypeValue(value, typeInfo);

				var task = value as Task;
				if (task != null)
				{
					var typeParameters = typeInfo.GenericTypeArguments;
					var typeName =
						typeParameters.Length == 0
							? "Task"
							: string.Format(CultureInfo.CurrentCulture, "Task<{0}>", string.Join(",", typeParameters.Select(t => FormatTypeName(t))));

					return string.Format(CultureInfo.CurrentCulture, "{0} {{ Status = {1} }}", typeName, task.Status);
				}

				// TODO: ValueTask?

				var isAnonymousType = typeInfo.IsAnonymousType();
				if (!isAnonymousType)
				{
					var toString = type.GetRuntimeMethod("ToString", EmptyTypes);

					if (toString != null && toString.DeclaringType != typeof(object))
#if XUNIT_NULLABLE
						return ((string?)toString.Invoke(value, EmptyObjects)) ?? "null";
#else
						return ((string)toString.Invoke(value, EmptyObjects)) ?? "null";
#endif
				}

				return FormatComplexValue(value, depth, type, isAnonymousType);
			}
			catch (Exception ex)
			{
				// Sometimes an exception is thrown when formatting an argument, such as in ToString.
				// In these cases, we don't want xunit to crash, as tests may have passed despite this.
				return string.Format(CultureInfo.CurrentCulture, "{0} was thrown formatting an object of type \"{1}\"", ex.GetType().Name, value.GetType());
			}

try
    {
        using var stream = File.OpenRead(pdbPath);
        using var provider = MetadataReaderProvider.FromPortablePdbStream(stream);
        var reader = provider.GetMetadataReader();
        var id = reader.DebugMetadataHeader?.Id;
        if (id is not { Length: >= 16 })
            return false;

        Span<byte> guidBytes = stackalloc byte[16];
        id.Value.AsSpan(0, 16).CopyTo(guidBytes);
        var actualGuid = new Guid(guidBytes);
        if (actualGuid == expectedGuid)
            return true;

        log?.Invoke($"Skipping mismatched PDB from symbol package: expected {expectedGuid:D}; found {actualGuid:D}");
        return false;
    }
    catch (Exception ex)
    {
        log?.Invoke($"Could not read PDB identity from {Path.GetFileName(pdbPath)}: {ex.Message}");
        return false;
    }

var result = new NuspecData();


    XNamespace ns = doc.Root?.GetDefaultNamespace() ?? XNamespace.None;

    result.ManifestVersion = GetManifestVersion(ns);


    var metadata = doc.Root?.Element(ns + "metadata");

    if (metadata == null) return result;


    result.PackageName = metadata.Element(ns + "id")?.Value;

    result.Version = metadata.Element(ns + "version")?.Value;

    result.Description = metadata.Element(ns + "description")?.Value;

    result.Authors = metadata.Element(ns + "authors")?.Value;

    var repositoryElement = metadata.Element(ns + "repository");

    result.Repository = repositoryElement?.Attribute("url")?.Value;

    result.RepositoryType = repositoryElement?.Attribute("type")?.Value;

    result.RepositoryCommit = repositoryElement?.Attribute("commit")?.Value;


    // Parse license (prefer expression over file or URL)
    var licenseElement = metadata.Element(ns + "license");

    if (licenseElement != null)
    {
        string? licenseType = licenseElement.Attribute("type")?.Value;
        if (licenseType?.Equals("expression", StringComparison.OrdinalIgnoreCase) == true)
        {
            result.License = licenseElement.Value;
        }
        else if (licenseType?.Equals("file", StringComparison.OrdinalIgnoreCase) == true)
        {
            result.License = $"(file: {licenseElement.Value})";
        }
    }

    // Fallback to deprecated licenseUrl if no license element
    if (string.IsNullOrEmpty(result.License))
    {
        var licenseUrl = metadata.Element(ns + "licenseUrl")?.Value;
        result.LicenseUrl = licenseUrl;
        if (!string.IsNullOrEmpty(licenseUrl) && !licenseUrl.Contains("LICENSE"))
        {
            if (licenseUrl.StartsWith("https://licenses.nuget.org/"))
            {
                result.License = licenseUrl.Replace("https://licenses.nuget.org/", "");
            }
        }
    }
    else
    {
        result.LicenseUrl = metadata.Element(ns + "licenseUrl")?.Value;
    }


    // Parse package types
    var packageTypes = metadata.Element(ns + "packageTypes");

    if (packageTypes != null)
    {
        foreach (var pt in packageTypes.Elements(ns + "packageType"))
        {
            string? typeName = pt.Attribute("name")?.Value;
            if (typeName != null)
            {
                result.PackageTypes ??= [];
                result.PackageTypes.Add(typeName);
                if (typeName.Equals("DotnetTool", StringComparison.OrdinalIgnoreCase))
                {
                    result.IsToolPackage = true;
                }
            }
        }
    }


    // Parse readme file path
    result.ReadmeFile = metadata.Element(ns + "readme")?.Value;


    // Parse dependencies
    var dependencies = metadata.Element(ns + "dependencies");

    if (dependencies != null)
    {
        foreach (var group in dependencies.Elements(ns + "group"))
        {
            string? tfm = group.Attribute("targetFramework")?.Value;
            var depGroup = new DependencyGroup { TargetFramework = tfm ?? "any" };

            foreach (var dep in group.Elements(ns + "dependency"))
            {
                depGroup.Dependencies.Add(new PackageDependency
                {
                    Id = dep.Attribute("id")?.Value ?? "",
                    Version = dep.Attribute("version")?.Value ?? ""
                });
            }

            result.DependencyGroups ??= [];
            result.DependencyGroups.Add(depGroup);
        }

        // Handle dependencies without groups
        var ungroupedDeps = dependencies.Elements(ns + "dependency").ToList();
        if (ungroupedDeps.Count > 0)
        {
            var depGroup = new DependencyGroup { TargetFramework = "any" };
            foreach (var dep in ungroupedDeps)
            {
                depGroup.Dependencies.Add(new PackageDependency
                {
                    Id = dep.Attribute("id")?.Value ?? "",
                    Version = dep.Attribute("version")?.Value ?? ""
                });
            }
            result.DependencyGroups ??= [];
            result.DependencyGroups.Add(depGroup);
        }
    }


    return result;

if (!Directory.Exists(root))
        return;


    foreach (var category in categories)
    {
        if (cancellationToken.IsCancellationRequested)
            return;

        string[] directories;
        try
        {
            directories = Directory.GetDirectories(root, $"{category.Prefix}*");
        }
        catch
        {
            continue;
        }

        foreach (var directory in directories)
        {
            if (cancellationToken.IsCancellationRequested)
                return;

            var name = Path.GetFileName(directory);
            if (name.Equals(category.Current, StringComparison.OrdinalIgnoreCase))
                continue;
            if (!name.StartsWith(category.Prefix, StringComparison.OrdinalIgnoreCase))
                continue;
            if (!IsSameOrChildPath(directory, root))
                continue;

            var size = GetDirectorySizeBestEffort(directory);
            try
            {
                Directory.Delete(directory, recursive: true);
                Interlocked.Add(ref s_maintenanceBytesFreed, size);
                Interlocked.Increment(ref s_maintenanceDirectoriesDeleted);
            }
            catch
            {
                // Cache cleanup is best-effort.
            }
        }
    }

var methods = ImmutableArray.CreateBuilder<MethodIdentity>();

    var unsafeLeverageMethods = ImmutableArray.CreateBuilder<MethodIdentity>();

    var calls = ImmutableArray.CreateBuilder<DirectCall>();

    var unsafeEvidence = ImmutableArray.CreateBuilder<UnsafeEvidence>();

    var diagnostics = ImmutableArray.CreateBuilder<AnalysisDiagnostic>();

    var optimizationOpportunities = ImmutableArray.CreateBuilder<OptimizationOpportunity>();

    var bodySignals = new Dictionary<int, BodySignals>();

    var suppressedOpportunityTokens = new HashSet<int>();

    var exceptionTypeNames = ComputeExceptionTypeNames();

    int none = 0, impl = 0, expl = 0;


    foreach (var typeHandle in _reader.TypeDefinitions)
    {
        var typeDef = _reader.GetTypeDefinition(typeHandle);
        // Source-generated types (JSON/regex/etc. carry [GeneratedCode]) are not
        // actionable source-shape opportunities, so skip optimization-opportunity
        // collection for them (they are still indexed for calls/leverage/signals).
        bool typeSourceGenerated = HasGeneratedCodeAttribute(typeDef.GetCustomAttributes());
        foreach (var methodHandle in typeDef.GetMethods())
        {
            try
            {
                var methodDef = _reader.GetMethodDefinition(methodHandle);
                var scope = CreateScope(typeDef, methodDef);
                var caller = CreateMethodIdentity(typeHandle, methodHandle, methodDef, scope);
                // Tally the unsafe mode for every method, including bodiless
                // extern/abstract members (P/Invokes are a major source).
                switch (caller.CallerUnsafeMode)
                {
                    case CallerUnsafeMode.Explicit: expl++; break;
                    case CallerUnsafeMode.Implicit: impl++; break;
                    default: none++; break;
                }
                bool hasUnsafeApiMember = AddUnsafeApiMemberEvidence(caller, unsafeEvidence);
                bool hasUnsafeSignature = AddUnsafeSignatureEvidence(caller, unsafeEvidence);
                if (caller.CallerUnsafeMode != CallerUnsafeMode.None || hasUnsafeApiMember)
                    unsafeLeverageMethods.Add(caller);
                if (methodDef.RelativeVirtualAddress == 0)
                    continue;

                methods.Add(caller);
                var body = _peReader.GetMethodBody(methodDef.RelativeVirtualAddress);
                var il = body.GetILBytes() ?? [];
                bool hasUnsafeLocals = ScanLocals(body, caller, scope, unsafeEvidence);
                var loopRegions = CollectLoopRegions(il);
                var methodAttributes = methodDef.GetCustomAttributes();
                if (!typeSourceGenerated
                    && !HasGeneratedCodeAttribute(methodAttributes)
                    && !HasCompilerGeneratedAttribute(methodAttributes))
                    optimizationOpportunities.AddRange(CollectOptimizationOpportunities(il, caller, scope, loopRegions));
                else
                    suppressedOpportunityTokens.Add(caller.MetadataToken);
                var signals = CollectBodySignals(il, body, scope, loopRegions);
                if (signals.Newarr > 0 || signals.Throws > 0 || signals.Catches > 0 || signals.Finallys > 0 || signals.Boxes > 0)
                    bodySignals[caller.MetadataToken] = signals;
                ScanBody(il, caller, scope, calls, unsafeEvidence,
                    includeIndirectOpcodes: hasUnsafeApiMember || hasUnsafeSignature || hasUnsafeLocals,
                    loopRegions);
            }
            catch (Exception ex) when (IsRecoverableMethodFailure(ex))
            {
                diagnostics.Add(new AnalysisDiagnostic(
                    MetadataTokens.GetToken(methodHandle),
                    MethodLabel(typeHandle, methodHandle),
                    $"{ex.GetType().Name}: {ex.Message}"));
            }
        }
    }


    return (methods.ToImmutable(), calls.ToImmutable(), unsafeEvidence.ToImmutable(), diagnostics.ToImmutable(),
        optimizationOpportunities.ToImmutable(), unsafeLeverageMethods.ToImmutable(), new UnsafeModeBreakdown(none, impl, expl), bodySignals,
        BuildInAssemblyExceptionMap(), suppressedOpportunityTokens, exceptionTypeNames);

if (parseResult.Errors.Any(e => e.SymbolResult == symbolResult))
        {
            builder.Append('!');
        }


        switch (symbolResult)
        {
            case DirectiveResult { Directive: not DiagramDirective }:
                break;

            case ArgumentResult argumentResult:
            {
                var includeArgumentName =
                    argumentResult.Argument.FirstParent!.Symbol is Command { HasArguments: true, Arguments.Count: > 1 };

                if (includeArgumentName)
                {
                    builder.Append("[ ");
                    builder.Append(argumentResult.Argument.Name);
                    builder.Append(' ');
                }

                if (argumentResult.Argument.Arity.MaximumNumberOfValues > 0)
                {
                    ArgumentConversionResult conversionResult = argumentResult.GetArgumentConversionResult();
                    switch (conversionResult.Result)
                    {
                        case ArgumentConversionResultType.NoArgument:
                            break;
                        case ArgumentConversionResultType.Successful:
                            switch (conversionResult.Value)
                            {
                                case string s:
                                    builder.Append($"<{s}>");
                                    break;

                                case IEnumerable items:
                                    builder.Append('<');
                                    builder.Append(
                                        string.Join("> <",
                                                    items.Cast<object>().ToArray()));
                                    builder.Append('>');
                                    break;

                                default:
                                    builder.Append('<');
                                    builder.Append(conversionResult.Value);
                                    builder.Append('>');
                                    break;
                            }

                            break;

                        default: // failures
                            builder.Append('<');
                            builder.Append(string.Join("> <", symbolResult.Tokens.Select(t => t.Value)));
                            builder.Append('>');

                            break;
                    }
                }

                if (includeArgumentName)
                {
                    builder.Append(" ]");
                }

                break;
            }

            default:
            {
                OptionResult? optionResult = symbolResult as OptionResult;

                if (optionResult is { Implicit: true })
                {
                    builder.Append('*');
                }

                builder.Append("[ ");

                if (optionResult is not null)
                {
                    builder.Append(optionResult.IdentifierToken?.Value ?? optionResult.Option.Name);
                }
                else
                {
                    builder.Append(((CommandResult)symbolResult).IdentifierToken.Value);
                }

                foreach (SymbolResult child in symbolResult.SymbolResultTree.GetChildren(symbolResult))
                {
                    if (child is ArgumentResult arg &&
                        (arg.Argument.ValueType == typeof(bool) ||
                         arg.Argument.Arity.MaximumNumberOfValues == 0))
                    {
                        continue;
                    }

                    builder.Append(' ');

                    Diagram(builder, child, parseResult);
                }

                builder.Append(" ]");
                break;
            }
        }

if (!memberSymbol.IsStatic || memberSymbol is IMethodSymbol)
		// assume initialized, if nonstatic or method to avoid spurious results
		return true;


	var semantics = context.SemanticModel;

	var declarationReference = memberSymbol.DeclaringSyntaxReferences.First();

	var declarationSyntax = declarationReference.GetSyntax();

	if (declarationSyntax is PropertyDeclarationSyntax prop
		&& (prop.Initializer != null
			|| prop.AccessorList?.Accessors.FirstOrDefault(decl => decl.Kind() == SyntaxKind.GetAccessorDeclaration)?.Body != null
			|| prop.ExpressionBody != null))
		return true;


	if (declarationSyntax is VariableDeclaratorSyntax field && field.Initializer != null)
		return true;


	var declarationContainer = declarationSyntax.FirstAncestorOrSelf<TypeDeclarationSyntax>()!;

	var staticConstructors =
		declarationContainer
			.DescendantNodes()
			.OfType<ConstructorDeclarationSyntax>()
			.Where(ctor => ctor.Modifiers.Any(SyntaxKind.StaticKeyword));


	foreach (var ctor in staticConstructors)
	{
		// Look for direct assignments to the member
		var assignments =
			ctor
				.DescendantNodes(descendIntoChildren: _ => true, descendIntoTrivia: false)
				.OfType<AssignmentExpressionSyntax>()
				.Where(assignment =>
				{
					var assignedSymbol = semantics.GetSymbolInfo(assignment.Left).Symbol;
					return SymbolEqualityComparer.Default.Equals(assignedSymbol?.OriginalDefinition, memberSymbol);
				});

		if (assignments.Any())
			return true;
	}


	return false;

var settings = new TemplateSettings ();


			bool relativeLinePragmas = host.GetHostOption ("UseRelativeLinePragmas") as bool? ?? false;

			foreach (Directive dt in pt.Directives) {
				switch (dt.Name.ToLowerInvariant ()) {
				case "template":
					string val = dt.Extract ("language");
					if (val != null)
						settings.Language = val;
					if (dt.Extract ("langversion") is string langVersion)
						settings.LangVersion = langVersion;
					val = dt.Extract ("debug");
					if (val != null)
						settings.Debug = string.Equals (val, "true", StringComparison.OrdinalIgnoreCase);
					val = dt.Extract ("inherits");
					if (val != null)
						settings.Inherits = val;
					val = dt.Extract ("culture");
					if (val != null) {
						var culture = System.Globalization.CultureInfo.GetCultureInfo (val);
						if (culture == null)
							pt.LogWarning ("Could not find culture '" + val + "'", dt.StartLocation);
						else
							settings.Culture = culture;
					}
					val = dt.Extract ("hostspecific");
					if (val != null) {
						if (string.Equals (val, "trueFromBase", StringComparison.OrdinalIgnoreCase)) {
							settings.HostPropertyOnBase = true;
							settings.HostSpecific = true;
						} else {
							settings.HostSpecific = string.Equals (val, "true", StringComparison.OrdinalIgnoreCase);
						}
					}
					val = dt.Extract ("CompilerOptions");
					if (val != null) {
						settings.CompilerOptions = val;
					}
					val = dt.Extract ("relativeLinePragmas");
					if (val != null) {
						relativeLinePragmas = string.Equals (val, "true", StringComparison.OrdinalIgnoreCase);
					}
					val = dt.Extract ("linePragmas");
					if (val != null) {
						settings.NoLinePragmas = string.Equals (val, "false", StringComparison.OrdinalIgnoreCase);
					}
					val = dt.Extract ("visibility");
					if (val != null) {
						settings.InternalVisibility = string.Equals (val, "internal", StringComparison.OrdinalIgnoreCase);
					}
					break;

				case "assembly":
					string name = dt.Extract ("name");
					if (name == null)
						pt.LogError ("Missing name attribute in assembly directive", dt.StartLocation);
					else
						settings.Assemblies.Add (name);
					break;

				case "import":
					string namespac = dt.Extract ("namespace");
					if (namespac == null)
						pt.LogError ("Missing namespace attribute in import directive", dt.StartLocation);
					else
						settings.Imports.Add (namespac);
					break;

				case "output":
					settings.Extension = dt.Extract ("extension");
					string encoding = dt.Extract ("encoding");
					if (encoding != null)
						settings.Encoding = Encoding.GetEncoding (encoding);
					break;

				case "include":
					throw new InvalidOperationException ("Include is handled in the parser");

				case "parameter":
					AddDirective (settings, host, nameof (ParameterDirectiveProcessor), dt);
					continue;

				default:
					string processorName = dt.Extract ("Processor");
					if (processorName == null)
						throw new InvalidOperationException ("Custom directive '" + dt.Name + "' does not specify a processor");

					AddDirective (settings, host, processorName, dt);
					continue;
				}
				ComplainExcessAttributes (dt, pt);
			}


			if (host is TemplateGenerator gen) {
				settings.HostType = gen.SpecificHostType;
				foreach (var processor in gen.GetAdditionalDirectiveProcessors ()) {
					settings.DirectiveProcessors [processor.GetType ().FullName] = processor;
				}
			}


			if (settings.HostType != null) {
				settings.Assemblies.Add (settings.HostType.Assembly.Location);
			}


			//initialize the custom processors
			foreach (var kv in settings.DirectiveProcessors) {
				kv.Value.Initialize (host);

				IRecognizeHostSpecific hs;
				if (settings.HostSpecific || (
				        !((IDirectiveProcessor)kv.Value).RequiresProcessingRunIsHostSpecific &&
				        ((hs = kv.Value as IRecognizeHostSpecific) == null || !hs.RequiresProcessingRunIsHostSpecific)))
					continue;

				settings.HostSpecific = true;
				pt.LogWarning ("Directive processor '" + kv.Key + "' requires hostspecific=true, forcing on.");
			}


			foreach (var kv in settings.DirectiveProcessors) {
				kv.Value.SetProcessingRunIsHostSpecific (settings.HostSpecific);
				if (kv.Value is IRecognizeHostSpecific hs)
					hs.SetProcessingRunIsHostSpecific (settings.HostSpecific);
				if (kv.Value is ISupportCodeGenerationOptions opt) {
					opt.SetCodeGenerationOptions (settings.CodeGenerationOptions);
				}
			}


			if (settings.Name == null)
				settings.Name = "GeneratedTextTransformation";

			if (settings.Namespace == null)
				settings.Namespace = $"{typeof (TextTransformation).Namespace}{new Random ().Next ():x}";


			//resolve the CodeDOM provider
			if (string.IsNullOrEmpty (settings.Language)) {
				settings.Language = "C#";
			}


			if (settings.Language == "C#v3.5") {
				pt.LogWarning ("The \"C#3.5\" Language attribute in template directives is deprecated, use the langversion attribute instead");
				settings.Provider = new CSharpCodeProvider (new Dictionary<string, string> {
					{ "CompilerVersion", "v3.5" }
				});
			} else {
				settings.Provider = CodeDomProvider.CreateProvider (settings.Language);
			}


			if (settings.Provider == null) {
				pt.LogError ("A provider could not be found for the language '" + settings.Language + "'");
				return settings;
			}


			settings.RelativeLinePragmas = relativeLinePragmas;


#if FEATURE_APPDOMAINS
			settings.CodeGenerationOptions.UseRemotingCallContext = true;
#endif

			return settings;

GuardArgumentNotNull(nameof(comparer), comparer);


			var expectedTracker = expected.AsNonStringTracker();

			var actualTracker = actual.AsNonStringTracker();

			var exception = default(Exception);


			try
			{
				var haveCollections =
					(expectedTracker != null && actualTracker != null) ||
					(expectedTracker != null && actual == null) ||
					(expected == null && actualTracker != null);

				if (!haveCollections)
				{
					try
					{
						if (!comparer.Equals(expected, actual))
							return;
					}
					catch (Exception ex)
					{
						exception = ex;
					}

					var formattedExpected = ArgumentFormatter.Format(expected);
					var formattedActual = ArgumentFormatter.Format(actual);

					var expectedIsString = expected is string;
					var actualIsString = actual is string;
					var isStrings =
						(expectedIsString && actual == null) ||
						(actualIsString && expected == null) ||
						(expectedIsString && actualIsString);

					if (isStrings)
						throw NotEqualException.ForEqualCollectionsWithError(null, formattedExpected, null, formattedActual, null, exception, "Strings");
					else
						throw NotEqualException.ForEqualValuesWithError(formattedExpected, formattedActual, exception);
				}
				else
				{
					int? mismatchedIndex = null;

					// If we have "known" comparers, we can ignore them and instead do our own thing, since we know
					// we want to be able to consume the tracker, and that's not type compatible.
					var itemComparer = default(IEqualityComparer);

					var aec = comparer as AssertEqualityComparer<T>;
					if (aec != null)
						itemComparer = aec.InnerComparer;
					else if (comparer == EqualityComparer<T>.Default)
						itemComparer = EqualityComparer<object>.Default;

					string formattedExpected;
					string formattedActual;
					int? expectedPointer = null;
					int? actualPointer = null;

					if (itemComparer != null)
					{
						try
						{
							bool result;

							// Call AssertEqualityComparer.Equals because it checks for IEquatable<> before using CollectionTracker
							if (aec != null)
								result = aec.Equals(expected, expectedTracker, actual, actualTracker, out mismatchedIndex);
							else
								result = CollectionTracker.AreCollectionsEqual(expectedTracker, actualTracker, itemComparer, itemComparer == AssertEqualityComparer<T>.DefaultInnerComparer, out mismatchedIndex);

							if (!result)
								return;

							// For NotEqual that doesn't throw, pointers are irrelevant, because
							// the values are considered to be equal
							formattedExpected = expectedTracker?.FormatStart() ?? "null";
							formattedActual = actualTracker?.FormatStart() ?? "null";
						}
						catch (Exception ex)
						{
							exception = ex;

							// When an exception was thrown, we want to provide a pointer so the user knows
							// which item was being inspected when the exception was thrown
							var expectedStartIdx = -1;
							var expectedEndIdx = -1;
							expectedTracker?.GetMismatchExtents(mismatchedIndex, out expectedStartIdx, out expectedEndIdx);

							var actualStartIdx = -1;
							var actualEndIdx = -1;
							actualTracker?.GetMismatchExtents(mismatchedIndex, out actualStartIdx, out actualEndIdx);

							expectedPointer = null;
							formattedExpected = expectedTracker?.FormatIndexedMismatch(expectedStartIdx, expectedEndIdx, mismatchedIndex, out expectedPointer) ?? ArgumentFormatter.Format(expected);

							actualPointer = null;
							formattedActual = actualTracker?.FormatIndexedMismatch(actualStartIdx, actualEndIdx, mismatchedIndex, out actualPointer) ?? ArgumentFormatter.Format(actual);
						}
					}
					else
					{
						try
						{
							if (!comparer.Equals(expected, actual))
								return;
						}
						catch (Exception ex)
						{
							exception = ex;
						}

						formattedExpected = ArgumentFormatter.Format(expected);
						formattedActual = ArgumentFormatter.Format(actual);
					}

#if XUNIT_NULLABLE
					string? collectionDisplay = null;
#else
					string collectionDisplay = null;
#endif

