                _completedAnalyzersForCompilation.Add(analyzer);
                fullCompilationDiagnostics = true;
                fullSyntaxDiagnosticsForTree = true;
                fullSyntaxDiagnosticsForAdditionalFile = true;
                fullSemanticDiagnosticsForTree = true;
